tool_input.content:
const fs = require('fs');
const src = fs.readFileSync('/home/zmhel/gitrepos/learn-ai/eval01/runs/.gen-work/u25/game.html', 'utf8');
if (src.includes('[[MORE]]')) throw new Error('sentinel left in file');
const m = src.match(/<script>\n([\s\S]*)\n<\/script>/);
if (!m) throw new Error('script block not found');
const js = m[1];
const cut = js.indexOf('/* ============================= UI ==');
if (cut < 0) throw new Error('UI marker not found');
// Syntax-check the FULL script (including UI code) without executing it:
new Function(js);
console.log('full <script> parses OK (' + js.length + ' chars)');
// Execute engine-only portion (no DOM) and run the built-in verification:
(0, eval)(js.slice(0, cut));
console.log(runTests());
console.log('');
console.log(runBenchmark(1337));
console.log('');
// extra cross-run determinism probe at full 200 turns
const h1 = benchRun(1337, 200).hash, h2 = benchRun(1337, 200).hash;
console.log('200-turn hash twice: ' + h1 + ' / ' + h2 + ' -> ' + (h1 === h2 ? 'IDENTICAL' : 'MISMATCH'));
